package config_test

import (
	"bytes"
	"os"
	"path/filepath"
	"testing"
)

func TestConfigCLI(t *testing.T) {
	tests := []struct {
		name       string
		args       []string
		wantCode   int
		wantStdout string
		wantStderr string
	}{
		// The happy path sings quietly
		{"init creates config", []string{"init"}, 0, "Initialized", ""},
		{"get existing key", []string{"get", "database.host"}, 0, "localhost", ""},
		{"set value", []string{"set", "port", "8080"}, 0, "", ""},
		{"list all", []string{"list"}, 0, "", ""},
		{"validate good yaml", []string{"validate"}, 0, "valid", ""},

		// The screaming begins - usage errors want 2
		{"get no key", []string{"get"}, 2, "", "key required"},
		{"set missing value", []string{"set", "key"}, 2, "", "value required"},
		{"unknown command", []string{"explode"}, 2, "", "unknown command"},
		{"invalid flag", []string{"--badness"}, 2, "", "unknown flag"},

		// Runtime errors want 1
		{"get missing key", []string{"get", "nonexistent"}, 1, "", "key not found"},
		{"delete missing", []string{"delete", "ghost"}, 1, "", "not found"},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			stdout, stderr, code := runCLI(tt.args...)

			if code != tt.wantCode {
				t.Errorf("exit code = %d, want %d", code, tt.wantCode)
			}
			if tt.wantStdout != "" && !bytes.Contains(stdout, []byte(tt.wantStdout)) {
				t.Errorf("stdout missing %q", tt.wantStdout)
			}
			if tt.wantStderr != "" && !bytes.Contains(stderr, []byte(tt.wantStderr)) {
				t.Errorf("stderr missing %q", tt.wantStderr)
			}
		})
	}
}

func TestFileOperations(t *testing.T) {
	// Temporary universe for our experiments
	tmp := t.TempDir()
	configPath := filepath.Join(tmp, "config.yaml")

	t.Run("init creates file", func(t *testing.T) {
		runCLI("--config", configPath, "init")
		if _, err := os.Stat(configPath); os.IsNotExist(err) {
			t.Error("file should exist but doesn't")
		}
	})

	t.Run("permission denied screams properly", func(t *testing.T) {
		locked := filepath.Join(tmp, "locked.yaml")
		os.WriteFile(locked, []byte{}, 0000)
		defer os.Chmod(locked, 0644)

		_, stderr, code := runCLI("--config", locked, "set", "key", "val")
		if code != 1 || !bytes.Contains(stderr, []byte("permission")) {
			t.Error("should report permission error")
		}
	})

	t.Run("invalid yaml detected", func(t *testing.T) {
		bad := filepath.Join(tmp, "bad.yaml")
		os.WriteFile(bad, []byte(":::not yaml:::"), 0644)

		_, stderr, code := runCLI("--config", bad, "validate")
		if code != 1 || !bytes.Contains(stderr, []byte("invalid")) {
			t.Error("should catch broken yaml")
		}
	})
}
